// Generated by Agent Team Kit 0.20.0. Do not edit.
// The team board computed from the local event log (~/.agent-team/<project>/events.jsonl, written by team-status.sh).
// Returns the same shape as the hosted board (board/supabase, GET team-report): { as_of, days, current, recent, flow, role }.
import { existsSync, readFileSync } from 'node:fs';

export const KINDS = ['status', 'handoff', 'bug', 'signoff', 'blocked', 'note', 'heartbeat'];
export const STATUSES = ['idle', 'working', 'waiting', 'blocked', 'review', 'done'];
const MESSAGES = ['handoff', 'bug', 'signoff', 'blocked'];
// Minutes a thread in each status may go without a report before it counts as gone quiet (stale).
export const STALE_MINUTES = { working: 30, waiting: 30, review: 30, blocked: 30 };
const ROLE = /^[a-z0-9][a-z0-9_-]{0,59}$/;

const text = (v, max) => {
  const s = typeof v === 'string' ? v.trim() : typeof v === 'number' ? String(v) : '';
  return s ? s.slice(0, max) : null;
};
const int = (v) => {
  const n = typeof v === 'number' ? v : parseInt(String(v ?? '').replace(/[^0-9]/g, ''), 10);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : null;
};

/** A report as a board row, or throws an Error saying what is wrong with it. Accepts `to` or `to_role`. */
export function toRow(b, now = new Date()) {
  if (!b || typeof b !== 'object') throw new Error('a report is a JSON object');
  const role = (text(b.role, 60) ?? '').toLowerCase().replace(/[^a-z0-9_-]+/g, '-');
  if (!ROLE.test(role)) throw new Error("role must be a brief's slug, like backend-dev");
  const kind = text(b.kind, 20) ?? 'status';
  if (!KINDS.includes(kind)) throw new Error(`kind must be one of ${KINDS.join(', ')}`);
  const status = text(b.status, 20);
  if (status && !STATUSES.includes(status)) throw new Error(`status must be one of ${STATUSES.join(', ')}`);
  if (kind === 'status' && !status) throw new Error('a status report needs a status');
  const to = text(b.to_role ?? b.to, 60)?.toLowerCase().replace(/[^a-z0-9_#-]+/g, '-') ?? null;
  if (MESSAGES.includes(kind) && !to) throw new Error(`${kind} needs a 'to' role`);
  const at = text(b.at, 40);
  const time = at && !Number.isNaN(Date.parse(at)) ? new Date(at) : now;
  const evidence = (Array.isArray(b.evidence) ? b.evidence : String(b.evidence ?? '').split(','))
    .map((e) => String(e).trim()).filter(Boolean).slice(0, 20).map((e) => e.slice(0, 300));
  const severity = int(b.severity);
  return {
    id: text(b.id, 80) ?? `${time.getTime()}-${Math.random().toString(36).slice(2, 10)}`,
    at: time.toISOString(),
    role,
    instance: text(b.instance, 60),
    kind,
    status,
    task: text(b.task, 300),
    issue: int(b.issue),
    pr: int(b.pr),
    branch: text(b.branch, 200),
    commit: text(b.commit, 40),
    // The team version the role's checkout runs: the last commit that changed .agent-team (report.mjs fills it).
    team_version: /^[0-9a-f]{7,40}$/.test(String(b.team_version ?? '')) ? String(b.team_version) : null,
    platform: text(b.platform, 20),
    to_role: to,
    severity: severity && severity <= 4 ? severity : null,
    evidence,
    detail: text(b.detail, 2000),
    source: text(b.source, 60) ?? 'team-status.sh',
    session: text(b.session, 120),
  };
}

/** Every valid row in a JSONL log, oldest first. Bad lines are skipped. */
export function readLog(file) {
  if (!existsSync(file)) return [];
  const rows = [];
  const lines = readFileSync(file, 'utf8').split('\n');
  for (let i = 0; i < lines.length; i++) {
    if (!lines[i].trim()) continue;
    try {
      const row = toRow(JSON.parse(lines[i]));
      if (!lines[i].includes('"id"')) row.id = `line-${i + 1}`;
      rows.push(row);
    } catch { /* not a report */ }
  }
  return rows.sort((a, b) => a.at.localeCompare(b.at));
}

/** The board: where every thread stands, the recent feed, the hand-off flow and one role's history. */
export function summarize(rows, { now = new Date(), days = 7, role = '', staleMinutes = {} } = {}) {
  const limits = { ...STALE_MINUTES, ...staleMinutes };
  const t = now.getTime();
  const key = (r) => `${r.role}#${r.instance ?? ''}`;
  const lastAny = new Map(), lastStatus = new Map(), lastMsg = new Map(), hooked = new Set(), lastVersion = new Map();
  for (const r of rows) {
    const k = key(r);
    lastAny.set(k, r.at);
    if (r.team_version) lastVersion.set(k, { version: r.team_version, at: r.at });
    if (r.source === 'hook') hooked.add(k);
    if (r.status) lastStatus.set(k, r);
    if ((r.kind === 'handoff' || r.kind === 'blocked') && r.to_role) lastMsg.set(k, r);
  }
  const current = [];
  for (const [k, s] of lastStatus) {
    const last = lastAny.get(k);
    const m = lastMsg.get(k);
    current.push({
      role: s.role, instance: s.instance, status: s.status, task: s.task, issue: s.issue, pr: s.pr, branch: s.branch,
      commit: s.commit, platform: s.platform, detail: s.detail, session: s.session,
      status_at: s.at, last_at: last,
      age_s: Math.max(0, Math.round((t - Date.parse(last)) / 1000)),
      stale: s.status in limits && t - Date.parse(last) > limits[s.status] * 60_000,
      // No hook event from this thread: it reports only for itself (another coding agent, or hooks off), so it can go quiet.
      self_reported: !hooked.has(k),
      // The team version it last reported running (null from a kit before 0.16, or a report without git).
      team_version: lastVersion.get(k)?.version ?? null,
      team_version_at: lastVersion.get(k)?.at ?? null,
      waiting_on: (s.status === 'waiting' || s.status === 'blocked') && m && Date.parse(m.at) >= Date.parse(s.at) - 5000 ? m.to_role : null,
    });
  }
  current.sort((a, b) => b.last_at.localeCompare(a.last_at));
  const since = t - Math.min(Math.max(days, 1), 90) * 86_400_000;
  const newest = rows.filter((r) => Date.parse(r.at) >= since).reverse();
  const flowMap = new Map();
  for (const r of rows) {
    if (!MESSAGES.includes(r.kind) || !r.to_role || Date.parse(r.at) < t - 7 * 86_400_000) continue;
    const k = `${r.role}>${r.to_role}`;
    const f = flowMap.get(k) ?? { role: r.role, to_role: r.to_role, n: 0, last_at: r.at, last_kind: r.kind };
    f.n++; f.last_at = r.at; f.last_kind = r.kind;
    flowMap.set(k, f);
  }
  const flow = [...flowMap.values()].sort((a, b) => b.last_at.localeCompare(a.last_at));
  const [wantRole, wantInst] = String(role).split('#');
  const history = wantRole ? rows.filter((r) => r.role === wantRole && (!wantInst || r.instance === wantInst)).reverse().slice(0, 100) : [];
  return { as_of: now.toISOString(), days, current, recent: newest.slice(0, 200), flow, role: history };
}
